import { CopyButton, CopyButtonIcon } from "@/registry/erbium/blocks/copy-button";
import {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuList,
} from "@/registry/erbium/ui/context-menu";

const Example = (args: {
  side: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
}) => (
  <ContextMenu>
    <ContextMenuTrigger className="rounded-xl border border-dashed bg-surface-panel p-8">
      Right click here
    </ContextMenuTrigger>
    <ContextMenuContent side={args.side} align={args.align}>
      <ContextMenuList>
        <CopyButton value="Erbium UI" render={<ContextMenuItem />}>
          <CopyButtonIcon />
          <span>Copy</span>
        </CopyButton>
        <ContextMenuItem>Paste</ContextMenuItem>
      </ContextMenuList>
    </ContextMenuContent>
  </ContextMenu>
);

export default Example;
